use dd_core::{InstrumentId, MAX_INSTRUMENTS};

/// Average-cost position with realised/unrealised P&L in quote currency.
#[derive(Debug, Clone, Copy, Default)]
pub struct Position {
    pub qty: f64,
    pub avg_px: f64,
    pub mark: f64,
    pub realized: f64,
}

impl Position {
    #[inline(always)]
    pub fn unrealized(&self) -> f64 {
        self.qty * (self.mark - self.avg_px)
    }

    /// Applies a signed fill; returns realised P&L generated by it.
    #[inline]
    fn apply(&mut self, dq: f64, px: f64) -> f64 {
        let mut pnl = 0.0;
        if self.qty == 0.0 || self.qty.signum() == dq.signum() {
            // Opening or adding: blend the average price.
            let new_qty = self.qty + dq;
            self.avg_px = (self.avg_px * self.qty + px * dq) / new_qty;
            self.qty = new_qty;
        } else {
            // Reducing, closing, or flipping.
            let closed = dq.abs().min(self.qty.abs());
            pnl = closed * (px - self.avg_px) * self.qty.signum();
            let new_qty = self.qty + dq;
            if new_qty.abs() < 1e-12 {
                self.qty = 0.0;
                self.avg_px = 0.0;
            } else if new_qty.signum() != self.qty.signum() {
                self.qty = new_qty;
                self.avg_px = px; // flipped: remainder opened at fill price
            } else {
                self.qty = new_qty;
            }
        }
        self.mark = px;
        self.realized += pnl;
        pnl
    }
}

/// Fixed-size book of positions with O(1) incremental equity and gross exposure.
#[derive(Debug)]
pub struct Portfolio {
    positions: Box<[Position]>,
    cash_pnl: f64,
    fees: f64,
    unrealized: f64,
    gross: f64,
    starting_equity: f64,
}

impl Portfolio {
    pub fn new(starting_equity: f64) -> Self {
        Self {
            positions: vec![Position::default(); MAX_INSTRUMENTS].into_boxed_slice(),
            cash_pnl: 0.0,
            fees: 0.0,
            unrealized: 0.0,
            gross: 0.0,
            starting_equity,
        }
    }

    #[inline(always)]
    pub fn position(&self, id: InstrumentId) -> Position {
        self.positions[id.idx()]
    }

    /// Re-marks one instrument and updates aggregates incrementally (no full scan).
    #[inline]
    pub fn mark(&mut self, id: InstrumentId, px: f64) {
        let p = &mut self.positions[id.idx()];
        let (old_u, old_g) = (p.unrealized(), (p.qty * p.mark).abs());
        p.mark = px;
        self.unrealized += p.unrealized() - old_u;
        self.gross += (p.qty * p.mark).abs() - old_g;
    }

    #[inline]
    pub fn apply_fill(&mut self, id: InstrumentId, signed_qty: f64, px: f64, fee: f64) {
        let p = &mut self.positions[id.idx()];
        let (old_u, old_g) = (p.unrealized(), (p.qty * p.mark).abs());
        self.cash_pnl += p.apply(signed_qty, px);
        self.fees += fee;
        self.unrealized += p.unrealized() - old_u;
        self.gross += (p.qty * p.mark).abs() - old_g;
    }

    #[inline(always)]
    pub fn equity(&self) -> f64 {
        self.starting_equity + self.cash_pnl + self.unrealized - self.fees
    }
    #[inline(always)]
    pub fn gross_notional(&self) -> f64 {
        self.gross.max(0.0)
    }
    pub fn realized(&self) -> f64 {
        self.cash_pnl
    }
    pub fn fees(&self) -> f64 {
        self.fees
    }
    pub fn starting_equity(&self) -> f64 {
        self.starting_equity
    }

    /// Full recomputation, used by tests to verify incremental aggregates don't drift.
    pub fn recompute_unrealized(&self) -> f64 {
        self.positions.iter().map(Position::unrealized).sum()
    }
}
